#!/usr/bin/env node
// Deterministic writer/reader for intelligence entries — learned behavioral
// guidance captured from user corrections. This module is the ONLY code that
// ever creates, mutates, deletes, or indexes entry files; the extractor agent
// and the orchestrator both go through this CLI so every entry is schema-valid
// (schema.mjs validateIntelligenceEntry) and `INDEX.md` is always a faithful
// DERIVED view — never hand-edited, regenerated by every mutating verb
// (mirrors the profile.mjs render / manifest.mjs discipline).
//
// Entry files: `<dir>/<name>.md` — flat `key: value` frontmatter between `---`
// fences (provenance flattened to provenance_* keys; no YAML nesting, the
// parser is a line scanner) + body sections `## Trigger` / `## Directive` /
// `## Why` in that exact order. parse → serialize round-trips byte-identically
// for files this module wrote (`add` verifies the round-trip before writing).
//
// Two read views — do not conflate them:
//   list       metadata view ({...frontmatter, path}, NO body) — index/inspection.
//   effective  CONSUMPTION view for dispatch-brief injection: the phase-routed
//              active set with the body sections hoisted to top-level keys
//              ({...frontmatter, path, trigger, directive, why}). Callers pass
//              dirs in precedence order — LATER dirs win `name` collisions
//              (workspace dir first, member dir second → member wins).
//
// Phase routing (PHASE_TYPES): planning → planning+all; implementation →
// implementation+all; review → implementation+review+all (reviewers verify
// compliance — superset by design). `--phase` takes a comma-separated union.
//
// Status lifecycle: `add` always creates a `candidate`. Acceptance is
// `promote` (plain candidates only — a candidate carrying `supersedes` is
// REFUSED and routed to `supersede`, otherwise old+new would both be active);
// `supersede <old> <new>` retires an active entry in favor of a candidate (and
// is the acceptance path for supersedes-carrying candidates); `drop` hard-
// deletes a candidate (never an active/superseded entry).
//
// Verbs:
//   node intelligence.mjs add <dir> --json <file|->
//   node intelligence.mjs list <dir> [--status <s>] [--type <t>] [--scope <s>]
//   node intelligence.mjs effective --phase <p[,p...]> [--candidates] <dir> [<dir>...]
//   node intelligence.mjs promote <dir> <name>
//   node intelligence.mjs drop <dir> <name>
//   node intelligence.mjs supersede <dir> <old> <new>
//   node intelligence.mjs index <dir>
//   node intelligence.mjs validate <dir|file>

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { INTELLIGENCE_ENTRY_SCHEMA, validateIntelligenceEntry } from "./schema.mjs";

// Phase → entry types injected for that phase (see header). Exported: the
// workflow spec and tests read the mapping from here, never re-encode it.
export const PHASE_TYPES = {
  planning: ["planning", "all"],
  implementation: ["implementation", "all"],
  review: ["implementation", "review", "all"],
};

// Deterministic frontmatter key order (the serializer always writes exactly this).
const FRONTMATTER_ORDER = [
  "schema", "name", "description", "type", "status", "scope",
  "provenance_run", "provenance_task", "provenance_date", "provenance_source",
  "supersedes",
];
const BODY_HEADINGS = ["## Trigger", "## Directive", "## Why"];
const INDEX_SECTIONS = ["active", "candidate", "superseded"];

function die(msg, code = 1) { process.stderr.write(msg + "\n"); process.exit(code); }
// Windows-safety: tolerate a UTF-8 BOM on read (e.g. a --json file written by
// PowerShell 5.1's Set-Content -Encoding utf8). This module never writes one.
function stripBOM(text) { return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text; }

// --- parse / serialize --------------------------------------------------------

// Text → { ...flat frontmatter, body: { trigger, directive, why } }. Throws on
// structural problems (fences, bad lines, missing/misordered headings); callers
// catch and die naming the file. Tolerates \r\n input, but byte-identical
// round-trip is only guaranteed for files this module wrote (always \n).
export function parseEntry(text) {
  const lines = stripBOM(text).split("\n").map((l) => (l.endsWith("\r") ? l.slice(0, -1) : l));
  if (lines[0] !== "---") throw new Error('missing opening "---" frontmatter fence on line 1');
  const close = lines.indexOf("---", 1);
  if (close < 0) throw new Error('missing closing "---" frontmatter fence');
  const entry = {};
  for (let i = 1; i < close; i++) {
    if (lines[i].trim() === "") continue;
    const sep = lines[i].indexOf(": "); // FIRST ": " — values may contain colons
    if (sep <= 0) throw new Error(`bad frontmatter line ${i + 1}: ${JSON.stringify(lines[i])} (expected "key: value")`);
    const key = lines[i].slice(0, sep).trim();
    if (key in entry) throw new Error(`duplicate frontmatter key "${key}"`);
    entry[key] = lines[i].slice(sep + 2).trim();
  }
  const body = lines.slice(close + 1);
  const idx = BODY_HEADINGS.map((h) => body.indexOf(h));
  const missing = BODY_HEADINGS.filter((h, i) => idx[i] < 0);
  if (missing.length) throw new Error(`missing body heading(s): ${missing.join(", ")}`);
  if (!(idx[0] < idx[1] && idx[1] < idx[2])) {
    throw new Error(`body headings out of order (expected ${BODY_HEADINGS.join(", ")})`);
  }
  const section = (from, to) => body.slice(from + 1, to).join("\n").trim();
  entry.body = {
    trigger: section(idx[0], idx[1]),
    directive: section(idx[1], idx[2]),
    why: section(idx[2], body.length),
  };
  return entry;
}

// Entry object → file text, keys in FRONTMATTER_ORDER (deterministic output).
export function serializeEntry(entry) {
  const lines = ["---"];
  for (const k of FRONTMATTER_ORDER) {
    if (entry[k] === undefined) continue;
    if (typeof entry[k] !== "string" || entry[k].includes("\n")) {
      throw new Error(`frontmatter ${k}: must be a single-line string`);
    }
    lines.push(`${k}: ${entry[k]}`);
  }
  const body = entry.body || {};
  lines.push(
    "---", "",
    "## Trigger", body.trigger ?? "", "",
    "## Directive", body.directive ?? "", "",
    "## Why", body.why ?? "",
  );
  return lines.join("\n") + "\n";
}

// Canonical (key-sorted) stringify for the add-time round-trip check.
function canon(v) {
  if (v === null || typeof v !== "object") return JSON.stringify(v);
  return "{" + Object.keys(v).sort().map((k) => JSON.stringify(k) + ":" + canon(v[k])).join(",") + "}";
}

// --- entry IO -------------------------------------------------------------------

function entryPath(dir, name) { return path.resolve(dir, `${name}.md`); }

// Non-dying read: { entry } or { error }. Corruption is always loud downstream.
function tryReadEntry(file) {
  let text;
  try { text = fs.readFileSync(file, "utf8"); } catch (e) { return { error: `cannot read: ${e.message}` }; }
  let entry;
  try { entry = parseEntry(text); } catch (e) { return { error: e.message }; }
  const { valid, errors } = validateIntelligenceEntry(entry);
  if (!valid) return { error: errors.join("; ") };
  const stem = path.basename(file, ".md");
  if (entry.name !== stem) return { error: `frontmatter name "${entry.name}" does not match filename "${stem}.md"` };
  return { entry };
}

function readEntry(file) {
  const r = tryReadEntry(file);
  if (r.error) die(`invalid entry ${file}: ${r.error}`);
  return r.entry;
}

function writeEntry(file, entry) {
  const { valid, errors } = validateIntelligenceEntry(entry);
  if (!valid) die(`refusing to write invalid entry ${file}:\n  ${errors.join("\n  ")}`);
  let text;
  try { text = serializeEntry(entry); } catch (e) { die(`cannot serialize ${file}: ${e.message}`); }
  fs.writeFileSync(file, text);
}

// Every *.md except INDEX.md, parsed + validated (any bad file → die naming it).
function readEntries(dir) {
  if (!fs.existsSync(dir)) return [];
  const files = fs.readdirSync(dir).filter((f) => f.endsWith(".md") && f !== "INDEX.md").sort();
  return files.map((f) => {
    const file = path.resolve(dir, f);
    return { entry: readEntry(file), path: file };
  });
}

const byName = (a, b) => (a.entry.name < b.entry.name ? -1 : a.entry.name > b.entry.name ? 1 : 0);

// --- INDEX.md (derived view; regenerated by every mutating verb) ----------------

function renderIndex(dir, entries) {
  const lines = [
    "# Intelligence Index (generated view)",
    "<!-- Generated from entry frontmatter by lib/intelligence.mjs. Do NOT hand-edit:",
    "     entries are the source of truth; regenerate with `intelligence.mjs index`. -->",
    `GENERATED: ${new Date().toISOString()}`,
    `DIR: ${path.resolve(dir)}`,
    "",
  ];
  for (const status of INDEX_SECTIONS) {
    lines.push(`## ${status}`);
    const group = entries.filter((e) => e.entry.status === status).sort(byName);
    if (group.length === 0) { lines.push("(none)"); continue; }
    for (const { entry } of group) {
      const item = `- ${entry.name} [${entry.type}/${entry.scope}] — ${entry.description}`;
      lines.push(status === "superseded" ? item : `${item} (since ${entry.provenance_date})`);
    }
  }
  return lines.join("\n") + "\n";
}

// Validates every entry first (readEntries dies on a bad one → INDEX untouched).
function writeIndex(dir) {
  const entries = readEntries(dir);
  const file = path.resolve(dir, "INDEX.md");
  fs.writeFileSync(file, renderIndex(dir, entries));
  return file;
}

// --- verbs ----------------------------------------------------------------------

const ADD_INPUT_KEYS = ["name", "description", "type", "scope", "provenance", "trigger", "directive", "why", "supersedes"];
const PROVENANCE_KEYS = ["run", "task", "date", "source"];

function cmdAdd(dir, args) {
  const j = args.indexOf("--json");
  if (!dir || j < 0 || args[j + 1] === undefined) die("usage: intelligence.mjs add <dir> --json <file|->");
  const src = args[j + 1];
  let raw;
  try { raw = fs.readFileSync(src === "-" ? 0 : src, "utf8"); }
  catch (e) { die(`cannot read ${src === "-" ? "stdin" : src}: ${e.message}`); }
  let input;
  try { input = JSON.parse(stripBOM(raw)); } catch (e) { die(`input is not valid JSON: ${e.message}`); }
  if (input === null || typeof input !== "object" || Array.isArray(input)) die("input JSON must be an object");
  if ("status" in input) die('input must not set "status" — entries are always created as candidates (promote/supersede change status)');
  for (const k of Object.keys(input)) {
    if (!ADD_INPUT_KEYS.includes(k)) die(`unknown input key "${k}" (allowed: ${ADD_INPUT_KEYS.join(", ")})`);
  }
  const prov = input.provenance !== null && typeof input.provenance === "object" && !Array.isArray(input.provenance)
    ? input.provenance : {};
  for (const k of Object.keys(prov)) {
    if (!PROVENANCE_KEYS.includes(k)) die(`unknown provenance key "${k}" (allowed: ${PROVENANCE_KEYS.join(", ")})`);
  }
  const t = (v) => (typeof v === "string" ? v.trim() : v);
  const entry = {
    schema: INTELLIGENCE_ENTRY_SCHEMA,
    name: t(input.name),
    description: t(input.description),
    type: t(input.type),
    status: "candidate", // forced — never taken from input
    scope: t(input.scope),
    provenance_run: t(prov.run),
    provenance_task: t(prov.task),
    provenance_date: t(prov.date),
    provenance_source: t(prov.source),
    ...(input.supersedes !== undefined ? { supersedes: t(input.supersedes) } : {}),
    body: { trigger: t(input.trigger), directive: t(input.directive), why: t(input.why) },
  };
  const { valid, errors } = validateIntelligenceEntry(entry);
  if (!valid) die(`invalid entry:\n  ${errors.join("\n  ")}`);
  let text;
  try { text = serializeEntry(entry); } catch (e) { die(`cannot serialize entry: ${e.message}`); }
  let back;
  try { back = parseEntry(text); } catch (e) { die(`entry does not round-trip cleanly: ${e.message}`); }
  if (canon(back) !== canon(entry)) {
    die("entry does not round-trip cleanly (a value breaks the flat file format — e.g. a body containing a section heading line)");
  }
  const file = entryPath(dir, entry.name);
  if (fs.existsSync(file)) die(`entry already exists: ${file} — use supersede to replace it`);
  fs.mkdirSync(path.resolve(dir), { recursive: true });
  fs.writeFileSync(file, text);
  writeIndex(dir);
  process.stdout.write(file + "\n"); // last line = the absolute entry path (capturable)
}

const LIST_FLAGS = { "--status": "status", "--type": "type", "--scope": "scope" };

function cmdList(dir, args) {
  if (!dir) die("usage: intelligence.mjs list <dir> [--status <s>] [--type <t>] [--scope <s>]");
  const filters = {};
  for (let i = 0; i < args.length; i += 2) {
    const key = LIST_FLAGS[args[i]];
    if (!key) die(`unknown flag "${args[i]}" (known: ${Object.keys(LIST_FLAGS).join(", ")})`);
    if (args[i + 1] === undefined) die(`${args[i]} requires a value`);
    filters[key] = args[i + 1];
  }
  const rows = readEntries(dir) // missing dir → [] (not an error)
    .filter(({ entry }) => Object.entries(filters).every(([k, v]) => entry[k] === v))
    .sort(byName)
    .map(({ entry, path: p }) => { const { body, ...fm } = entry; return { ...fm, path: p }; });
  process.stdout.write(JSON.stringify(rows, null, 2) + "\n");
}

function cmdEffective(args) {
  let phaseArg = null, candidates = false;
  const dirs = [];
  for (let i = 0; i < args.length; i++) {
    if (args[i] === "--phase") { phaseArg = args[++i]; if (phaseArg === undefined) die("--phase requires a value"); }
    else if (args[i] === "--candidates") candidates = true;
    else dirs.push(args[i]);
  }
  if (!phaseArg || dirs.length === 0) die("usage: intelligence.mjs effective --phase <p[,p...]> [--candidates] <dir> [<dir>...]");
  const types = new Set();
  for (const p of phaseArg.split(",").map((s) => s.trim()).filter(Boolean)) {
    if (!PHASE_TYPES[p]) die(`unknown phase "${p}" (known: ${Object.keys(PHASE_TYPES).join(", ")})`);
    for (const t of PHASE_TYPES[p]) types.add(t);
  }
  if (types.size === 0) die("--phase requires at least one phase");
  const statuses = new Set(candidates ? ["active", "candidate"] : ["active"]); // superseded: never
  const merged = new Map(); // name → { entry, path }; later dirs win collisions
  for (const dir of dirs) {
    for (const e of readEntries(dir)) merged.set(e.entry.name, e); // missing dirs skipped silently
  }
  const rows = [...merged.values()]
    .filter(({ entry }) => statuses.has(entry.status) && types.has(entry.type))
    .sort(byName)
    .map(({ entry, path: p }) => {
      const { body, ...fm } = entry;
      return { ...fm, path: p, trigger: body.trigger, directive: body.directive, why: body.why };
    });
  process.stdout.write(JSON.stringify(rows, null, 2) + "\n");
}

function cmdPromote(dir, name) {
  if (!dir || !name) die("usage: intelligence.mjs promote <dir> <name>");
  const file = entryPath(dir, name);
  if (!fs.existsSync(file)) die(`no such entry: ${file}`);
  const entry = readEntry(file);
  if (entry.status !== "candidate") die(`only candidates can be promoted — "${name}" is ${entry.status}`);
  if (entry.supersedes !== undefined) {
    die(`candidate supersedes "${entry.supersedes}" — use: intelligence.mjs supersede ${dir} ${entry.supersedes} ${name}`);
  }
  entry.status = "active";
  writeEntry(file, entry);
  writeIndex(dir);
  process.stdout.write(`promoted ${name}: candidate -> active (${file})\n`);
}

function cmdDrop(dir, name) {
  if (!dir || !name) die("usage: intelligence.mjs drop <dir> <name>");
  const file = entryPath(dir, name);
  if (!fs.existsSync(file)) die(`no such entry: ${file}`);
  const entry = readEntry(file);
  if (entry.status !== "candidate") {
    die(`only candidates can be dropped — use supersede for active entries ("${name}" is ${entry.status})`);
  }
  fs.unlinkSync(file);
  writeIndex(dir);
  process.stdout.write(`dropped ${name} (deleted ${file})\n`);
}

function cmdSupersede(dir, oldName, newName) {
  if (!dir || !oldName || !newName) die("usage: intelligence.mjs supersede <dir> <old> <new>");
  const oldFile = entryPath(dir, oldName);
  const newFile = entryPath(dir, newName);
  if (!fs.existsSync(oldFile)) die(`no such entry: ${oldFile}`);
  if (!fs.existsSync(newFile)) die(`no such entry: ${newFile}`);
  const oldEntry = readEntry(oldFile);
  const newEntry = readEntry(newFile);
  if (oldEntry.status !== "active") die(`supersede target "${oldName}" must be active — it is ${oldEntry.status}`);
  if (newEntry.status !== "candidate") die(`replacement "${newName}" must be a candidate — it is ${newEntry.status}`);
  oldEntry.status = "superseded";
  newEntry.status = "active";
  newEntry.supersedes = oldName; // set, or confirm when the candidate already carried it
  // Validate both BEFORE writing either, so a bad pair never half-applies.
  for (const [f, e] of [[oldFile, oldEntry], [newFile, newEntry]]) {
    const { valid, errors } = validateIntelligenceEntry(e);
    if (!valid) die(`refusing supersede — resulting entry ${f} would be invalid:\n  ${errors.join("\n  ")}`);
  }
  writeEntry(oldFile, oldEntry);
  writeEntry(newFile, newEntry);
  writeIndex(dir);
  process.stdout.write(`superseded ${oldName} by ${newName} (${dir})\n`);
}

function cmdIndex(dir) {
  if (!dir) die("usage: intelligence.mjs index <dir>");
  if (!fs.existsSync(dir)) die(`no such directory: ${dir}`);
  const file = writeIndex(dir); // validates every entry; a bad one dies, INDEX untouched
  process.stdout.write(`wrote ${file}\n`);
}

function cmdValidate(target) {
  if (!target) die("usage: intelligence.mjs validate <dir|file>");
  if (!fs.existsSync(target)) die(`no such file or directory: ${target}`);
  const files = fs.statSync(target).isDirectory()
    ? fs.readdirSync(target).filter((f) => f.endsWith(".md") && f !== "INDEX.md").sort().map((f) => path.resolve(target, f))
    : [path.resolve(target)];
  const problems = [];
  for (const f of files) {
    const r = tryReadEntry(f);
    if (r.error) problems.push(`${f}: ${r.error}`);
  }
  if (problems.length) die("INVALID:\n  " + problems.join("\n  "));
  process.stdout.write("OK\n");
}

// --- CLI --------------------------------------------------------------------

// fileURLToPath (not URL.pathname): the latter yields "/E:/..." on Windows.
const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const [verb, ...rest] = process.argv.slice(2);
  switch (verb) {
    case "add": cmdAdd(rest[0], rest.slice(1)); break;
    case "list": cmdList(rest[0], rest.slice(1)); break;
    case "effective": cmdEffective(rest); break;
    case "promote": cmdPromote(rest[0], rest[1]); break;
    case "drop": cmdDrop(rest[0], rest[1]); break;
    case "supersede": cmdSupersede(rest[0], rest[1], rest[2]); break;
    case "index": cmdIndex(rest[0]); break;
    case "validate": cmdValidate(rest[0]); break;
    default: die("usage: intelligence.mjs <add|list|effective|promote|drop|supersede|index|validate> ...");
  }
}
